const AU={ctx:null,master:null,on:true,song:null,i:0,next:0,hold:0,
 init(){if(this.ctx)return;try{const A=window.AudioContext||window.webkitAudioContext;if(!A)return;this.ctx=new A();this.master=this.ctx.createGain();this.master.gain.value=this.on?.9:0;this.master.connect(this.ctx.destination);setInterval(()=>this.tick(),40)}catch(e){this.ctx=null}},
 resume(){try{if(!this.ctx||document.hidden)return;if(this.ctx.state!=='running')this.ctx.resume().then(()=>{this.next=this.ctx.currentTime+.05}).catch(()=>{});
  if(!this.unlocked){this.unlocked=true;const b=this.ctx.createBuffer(1,1,22050),src=this.ctx.createBufferSource();src.buffer=b;src.connect(this.ctx.destination);src.start(0)}}catch(e){}},
 setOn(v){this.on=v;if(this.master)this.master.gain.value=v?.9:0},
 ok(){return this.ctx&&this.ctx.state==='running'&&this.on},
 tone(f,t,d,type,v){const o=this.ctx.createOscillator(),g=this.ctx.createGain();o.type=type;o.frequency.setValueAtTime(f,t);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(v,t+.006);g.gain.setValueAtTime(v,t+Math.max(.008,d-.03));g.gain.linearRampToValueAtTime(0,t+d);o.connect(g).connect(this.master);o.start(t);o.stop(t+d+.02)},
 noise(t,d,v,f){const ctx=this.ctx,n=Math.max(1,Math.floor(ctx.sampleRate*d)),b=ctx.createBuffer(1,n,ctx.sampleRate),a=b.getChannelData(0);for(let i=0;i<n;i++)a[i]=(Math.random()*2-1)*(1-i/n);
  const s=ctx.createBufferSource();s.buffer=b;const fl=ctx.createBiquadFilter();fl.type='lowpass';fl.frequency.value=f;const g=ctx.createGain();g.gain.value=v;s.connect(fl).connect(g).connect(this.master);s.start(t)},
 play(name){if(this.song===name)return;this.song=name;this.i=0;if(this.ctx)this.next=Math.max(this.ctx.currentTime+.06,this.hold)},
 sched(arr,i,type,v,sd,t){const n=arr[i];if(!n||n==='-'||n==='.')return;let k=1;while(arr[(i+k)%arr.length]==='-'&&k<16)k++;this.tone(n2f(n),t,sd*k*.9,type,v)},
 tick(){if(!this.ctx||this.ctx.state!=='running'||!this.song)return;const s=SONGS[this.song];if(!s)return;const sd=60/s.bpm/2,now=this.ctx.currentTime;
  if(now<this.hold){this.next=this.hold;return}
  if(this.next<now)this.next=now+.02;
  while(this.next<now+.2){this.sched(s.lead,this.i%s.lead.length,'square',.035,sd,this.next);this.sched(s.bass,this.i%s.bass.length,'triangle',.08,sd,this.next);if(s.drum){const d=s.drum[this.i%s.drum.length];if(d==='h')this.noise(this.next,.03,.035,7000);else if(d==='k')this.noise(this.next,.07,.13,260)}this.i++;this.next+=sd}},
 jingle(name){if(!this.ok())return;const j=JINGLES[name],sd=60/j.bpm/2,t=this.ctx.currentTime+.04;
  for(const[arr,type,v]of[[j.lead,'square',.05],[j.bass||[],'triangle',.09]])arr.forEach((n,i)=>{if(n!=='-'&&n!=='.'){let k=1;while(arr[i+k]==='-')k++;this.tone(n2f(n),t+i*sd,sd*k*.9,type,v)}});
  this.hold=t+j.lead.length*sd+.15;this.next=this.hold},
 sfx(name){if(!this.ok())return;const t=this.ctx.currentTime+.005;
  switch(name){
   case'cur':this.tone(1200,t,.03,'square',.025);break;
   case'sel':this.tone(1568,t,.045,'square',.03);break;
   case'back':this.tone(784,t,.05,'square',.03);break;
   case'bump':this.tone(110,t,.07,'square',.05);break;
   case'door':this.noise(t,.14,.1,1200);this.tone(330,t,.08,'triangle',.07);this.tone(247,t+.08,.1,'triangle',.07);break;
   case'alert':this.tone(1760,t,.06,'square',.05);this.tone(2093,t+.07,.12,'square',.05);break;
   case'swing':this.noise(t,.08,.07,3000);break;
   case'fxnormal':this.noise(t,.1,.1,2000);break;
   case'fxfire':this.noise(t,.45,.14,900);this.tone(200,t,.3,'sawtooth',.03);break;
   case'fxwater':for(let i=0;i<6;i++)this.tone(600+i*130,t+i*.05,.05,'sine',.07);break;
   case'fxgrass':for(let i=0;i<4;i++)this.noise(t+i*.07,.05,.09,4500);break;
   case'fxrock':this.tone(90,t+.25,.12,'square',.07);this.noise(t+.25,.2,.16,600);break;
   case'fxflying':this.noise(t,.3,.12,2600);this.noise(t+.12,.2,.1,1800);break;
   case'fxdragon':this.noise(t,.35,.12,1400);for(let i=0;i<5;i++)this.tone(220+i*90,t+i*.05,.09,'sawtooth',.03);break;
   case'fxpsychic':for(let i=0;i<6;i++){this.tone(520+Math.sin(i)*160+i*60,t+i*.06,.08,'sine',.07)}break;
   case'fxelec':for(let i=0;i<9;i++)this.tone(i%2?1800:900,t+i*.035,.03,'square',.035);break;
   case'hit':this.noise(t,.12,.2,900);this.tone(160,t,.1,'square',.06);break;
   case'super':this.noise(t,.25,.28,600);this.tone(100,t,.2,'sawtooth',.07);break;
   case'faint':for(let i=0;i<10;i++)this.tone(700-i*55,t+i*.045,.05,'square',.04);break;
   case'throw':this.tone(500,t,.08,'triangle',.07);this.tone(760,t+.08,.08,'triangle',.07);break;
   case'pop':this.tone(900,t,.04,'square',.05);this.noise(t,.1,.1,2500);break;
   case'statup':for(let i=0;i<5;i++)this.tone(500+i*160,t+i*.04,.05,'square',.03);break;
   case'statdown':for(let i=0;i<5;i++)this.tone(1100-i*160,t+i*.04,.05,'square',.03);break;
   case'fxstatus':for(let i=0;i<4;i++)this.tone(1400+i*200,t+i*.06,.06,'sine',.05);break;
   case'evo':for(let i=0;i<16;i++)this.tone(330*Math.pow(2,(i%8)/12),t+i*.18,.16,'triangle',.06);break;
   case'buy':this.tone(1319,t,.06,'square',.04);this.tone(1760,t+.07,.1,'square',.04);break;
  }}};
