const bgSound=hidden=>{try{if(!AU.ctx)return;if(hidden){if(AU.ctx.state==='running')AU.ctx.suspend()}else if(AU.ctx.state==='suspended')AU.ctx.resume().then(()=>{AU.next=AU.ctx.currentTime+.05}).catch(()=>{})}catch(e){}};
